import{_ as r,C as o,o as t,c as l,a2 as i,b as s,w as a,a as d,E as c,a3 as p}from"./chunks/framework.CRkTBNIT.js";const I=JSON.parse('{"title":"Step 8: AI Integration & Predictive Delivery Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-integration.md","filePath":"07-ai-integration.md"}'),g={name:"07-ai-integration.md"};function m(u,e,h,f,y,A){const n=o("Mermaid");return t(),l("div",null,[e[1]||(e[1]=i('<h1 id="step-8-ai-integration-predictive-delivery-architecture" tabindex="-1">Step 8: AI Integration &amp; Predictive Delivery Architecture <a class="header-anchor" href="#step-8-ai-integration-predictive-delivery-architecture" aria-label="Permalink to &quot;Step 8: AI Integration &amp; Predictive Delivery Architecture&quot;">​</a></h1><h2 id="_1-ai-integration-scope-in-omnipost" tabindex="-1">1. AI Integration Scope in OmniPost <a class="header-anchor" href="#_1-ai-integration-scope-in-omnipost" aria-label="Permalink to &quot;1. AI Integration Scope in OmniPost&quot;">​</a></h2><p>OmniPost integrates predictive delivery optimization and pre-trained AI capabilities through standard APIs without training custom machine learning models from scratch.</p><h3 id="architectural-responsibilities" tabindex="-1">Architectural Responsibilities: <a class="header-anchor" href="#architectural-responsibilities" aria-label="Permalink to &quot;Architectural Responsibilities:&quot;">​</a></h3><ul><li><strong>Optimal Send-Time Optimization (STO)</strong>: Predicting recipient engagement probability based on historical open and interaction timestamps.</li><li><strong>Smart Subject-Line Generation &amp; Truncation</strong>: Generating concise, engaging subject lines with deterministic character caps.</li><li><strong>Delivery Anomaly Detection</strong>: Identifying statistical spikes in provider bounce rates or carrier filtering.</li></ul>',5)),(t(),s(p,null,{default:a(()=>[c(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Caller%5B%22Notification%20Payload%22%5D%20--%3E%20Engine%5B%22Core%20Ingestion%22%5D%0A%20%20%20%20Engine%20--%3E%20AIAnalyzer%5B%22Predictive%20Delivery%20Analyzer%20(AI%20API)%22%5D%0A%20%20%20%20AIAnalyzer%20--%3E%7CRecommended%20Send%20Window%7C%20Scheduler%5B%22Scheduled%20Job%20Store%22%5D%0A%20%20%20%20AIAnalyzer%20--%3E%7COptimized%20Subject%7C%20TemplateEngine%5B%22Template%20Personalizer%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<hr><h2 id="_2-why-use-a-pre-trained-api-vs-training-a-custom-model" tabindex="-1">2. Why Use a Pre-Trained API vs Training a Custom Model? <a class="header-anchor" href="#_2-why-use-a-pre-trained-api-vs-training-a-custom-model" aria-label="Permalink to &quot;2. Why Use a Pre-Trained API vs Training a Custom Model?&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">Pre-Trained API (OpenAI / Anthropic / Bedrock)</th><th style="text-align:left;">Custom Trained In-House Model</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Infrastructure Overhead</strong></td><td style="text-align:left;">Zero GPU management; stateless HTTP requests.</td><td style="text-align:left;">Multi-node GPU clusters (A100/H100), PyTorch training pipelines.</td></tr><tr><td style="text-align:left;"><strong>Cold-Start Time</strong></td><td style="text-align:left;">Ready in minutes using structured prompts.</td><td style="text-align:left;">Months of data labeling, data cleaning, and hyperparameter tuning.</td></tr><tr><td style="text-align:left;"><strong>Maintenance Burden</strong></td><td style="text-align:left;">Managed availability, automated upgrades.</td><td style="text-align:left;">Model drift monitoring, continuous retraining, data pipeline ops.</td></tr><tr><td style="text-align:left;"><strong>Total Cost</strong></td><td style="text-align:left;">Pay-per-token API cost (~$0.0005 per message).</td><td style="text-align:left;">Tens of thousands of dollars in fixed monthly cloud compute costs.</td></tr></tbody></table><hr><h2 id="_3-fallbacks-vendor-independence" tabindex="-1">3. Fallbacks &amp; Vendor Independence <a class="header-anchor" href="#_3-fallbacks-vendor-independence" aria-label="Permalink to &quot;3. Fallbacks &amp; Vendor Independence&quot;">​</a></h2><p>If the external AI provider times out or returns HTTP 429 rate limits:</p><ol><li><strong>Deterministic Rule Fallback</strong>: If optimal send-time prediction fails, the engine falls back to standard user quiet-hours evaluation (<code>preferences/routing.py</code>).</li><li><strong>Template Subject Fallback</strong>: If dynamic subject optimization fails, the engine renders the static registered subject template directly.</li><li><strong>Provider Abstraction Layer</strong>: The AI client is wrapped in a common interface, allowing immediate switching between OpenAI, Anthropic Claude, or local Ollama instances via environment variables.</li></ol>',7))])}const _=r(g,[["render",m]]);export{I as __pageData,_ as default};
